    """Données existantes : première programmation et chaînage des reprogrammations.

    Un même numéro déjà inscrit à plusieurs dates forme une seule chaîne de suivi :
    chaque inscription antérieure est considérée comme reprise par la suivante.
    """
    Container = apps.get_model('terminal', 'Container')
    chains = {}
    for c in Container.objects.order_by('container_number', 'scheduled_date'):
        chains.setdefault(c.container_number, []).append(c)

    for items in chains.values():
        first_date = items[0].scheduled_date
        previous = None
        for c in items:
            c.first_scheduled_date = first_date
            c.carried_from = previous
            c.save(update_fields=['first_scheduled_date', 'carried_from'])
            if previous is not None:
                previous.carry_decision = 'carried'
                previous.save(update_fields=['carry_decision'])
            previous = c


